<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_51taojinge_com_uc_post_content extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-51taojinge-com-uc-post-content', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $json = json_decode($html, true); if (isset($json['data']['body']['inner_imgs']) && count($json['data']['body']['inner_imgs'])) { $patterns = array(); $replacements = array(); foreach ($json['data']['body']['inner_imgs'] as $index => $inner_img) { $patterns[] = "<!--{img:{$index}}-->"; $replacements[] = '<img src="'.$inner_img['url'].'">'; } $item = str_replace($patterns, $replacements, $item); } return $item; } } new qqworld_collector_parse_51taojinge_com_uc_post_content; ?>